def total_pages(days):
    total = 0
    for pages in days:
        total = total + pages
    return total

goal = int(input())
days = [int(input()), int(input()), int(input())]
total = total_pages(days)
print(total)
if total >= goal:
    print("Цель достигнута")
else:
    print("Осталось", goal - total)
